set -e
cd "$(dirname "$0")"
cat > test-run.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# One test run: start surl's S3 endpoint on a free port with a random seed, run the app's
# upload against it, stop surl, and exit with the app's code. The seed is printed first, so a
# failed run's log says how to repeat it.
# Usage: sh test-run.sh [<seed>] [probe]     (no seed: draw one; probe: connect once first)
seed=${1:-$(od -An -N4 -tu4 /dev/urandom | tr -d ' ')}
echo "seed=$seed"
rm -rf store && mkdir -p store/photos
: > listening.txt
surl -v --s3-plaintext --random-seed "$seed" --directory store \
  --user AKIAIOSFODNN7EXAMPLE:s3cret --allow-uploads s3://127.0.0.1:0/ > listening.txt 2> surl.log &
pid=$!

# Wait for the Listening on line; a surl that exits first refused to start.
tries=0
until grep -q '^Listening on ' listening.txt; do
  if ! kill -0 "$pid" 2>/dev/null; then wait "$pid"; code=$?; cat surl.log >&2; exit "$code"; fi
  tries=$((tries + 1))
  if [ "$tries" -ge 100 ]; then kill "$pid"; echo "surl did not start in 10 s" >&2; exit 1; fi
  sleep 0.1
done
url=$(sed -n 's|^Listening on s3://|http://|p' listening.txt | tr -d '\r')

# A readiness check that connects is one more exchange before the app's.
if [ "$2" = probe ]; then curl -s -o /dev/null "$url"; fi

sh upload.sh "$url"
result=$?
kill "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
exit "$result"
EOF
cat > upload.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The app under test, as a script: a multipart upload of big.bin into the photos bucket.
# Usage: sh upload.sh <S3 endpoint URL>
sign="--aws-sigv4 aws:amz:us-east-1:s3 -u AKIAIOSFODNN7EXAMPLE:s3cret"
id=$(curl -sS $sign -X POST "${1}photos/big.bin?uploads" |
  sed -n 's|.*<UploadId>\([0-9a-f]*\)</UploadId>.*|\1|p')
echo "upload $id"

# The bug the test run trips over, standing in for your app's: it uses the upload ID as a
# name, and a name may not begin with a digit. Only some IDs bring it out.
case $id in
  [0-9]*) echo "failed: upload $id cannot be named" >&2; exit 1 ;;
esac

printf 'part one\n' > part1.bin
etag=$(curl -sS $sign -D - -o /dev/null -T part1.bin "${1}photos/big.bin?partNumber=1&uploadId=$id" |
  tr -d '\r' | sed -n 's/^[Ee][Tt]ag: //p')
printf '<CompleteMultipartUpload><Part><PartNumber>1</PartNumber><ETag>%s</ETag></Part></CompleteMultipartUpload>' \
  "$etag" > complete.xml
curl -sS -f $sign -o /dev/null --data-binary @complete.xml "${1}photos/big.bin?uploadId=$id" || exit
echo "stored big.bin"
EOF
cat > nonces.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Starts two HTTP servers with the same seed and one account, asks each for a file without a
# login, and says whether the Digest nonces of their 401s are the same.
for n in 1 2; do
  : > "http-$n.txt"
  surl --random-seed 3 --user alice:s3cret http://127.0.0.1:0/ > "http-$n.txt" 2> /dev/null &
  echo $! > "http-$n.pid"
done
for n in 1 2; do
  tries=0
  until grep -q '^Listening on ' "http-$n.txt"; do
    tries=$((tries + 1)); [ "$tries" -lt 100 ] || break; sleep 0.1
  done
  url=$(sed -n 's|^Listening on ||p' "http-$n.txt" | tr -d '\r')
  curl -s -o /dev/null -D - "${url}a.txt" | sed -n 's/.*nonce="\([0-9a-f]*\)".*/\1/p' | head -n 1 > "nonce-$n.txt"
  kill "$(cat "http-$n.pid")"
done
if [ -s nonce-1.txt ] && cmp -s nonce-1.txt nonce-2.txt; then echo "same nonce"; else echo "different nonces"; fi
EOF
sh test-run.sh 3 || true
